import { Component, Input } from '@angular/core';
import { PieService } from '../../services/pie.service';
import { AsyncPipe, NgFor, NgIf } from '@angular/common';
import { RouterLink, RouterLinkActive } from '@angular/router';
import { tap } from 'rxjs';
import { PRODUCT_ROUTES_TOKENS } from '../product.routes';

@Component({
  standalone: true,
  imports: [
    NgFor,
    NgIf,
    AsyncPipe,
    RouterLink,
    RouterLinkActive,
  ],
  selector: 'app-side-menu',
  templateUrl: './side-menu.component.html',
  styleUrls: ['./side-menu.component.css']
})
export class SideMenuComponent {
  @Input() customize = false;
  pies$ = this.pieService.filteredPies$;

  readonly customLink = `./${PRODUCT_ROUTES_TOKENS.CUSTOM}`;
  readonly detailsLink = `./${PRODUCT_ROUTES_TOKENS.DETAIL}`;

  constructor(
    private readonly pieService: PieService,
  ) {}
}
<div class="side-nav">
  <button
    *ngFor="let pie of pies$ | async"
    class="image-button"
    [routerLink]="[customize ? customLink : detailsLink]"
    routerLinkActive="active-link"
    [queryParams]="{productId: pie.id}"
    queryParamsHandling="merge"
  >
    <img
      [src]="pie.thumb"
      [alt]="pie.title"
    />
  </button>
</div>
